import sys
from math import comb

def generate_brute(num_rows):
    rows = []
    for r in range(num_rows):
        rows.append([comb(r, c) for c in range(r + 1)])
    return rows

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    rows = generate_brute(n)
    for row in rows:
        print(' '.join(map(str, row)))

import sys

def generate_opt(num_rows):
    rows = []
    for r in range(num_rows):
        if r == 0:
            rows.append([1])
        else:
            prev = rows[-1]
            row = [1] + [prev[c - 1] + prev[c] for c in range(1, r)] + [1]
            rows.append(row)
    return rows

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    rows = generate_opt(n)
    for row in rows:
        print(' '.join(map(str, row)))

import sys

def generate_best(num_rows):
    rows = []
    for r in range(num_rows):
        new_row = [1]
        if rows:
            prev = rows[-1]
            new_row += [a + b for a, b in zip(prev, prev[1:])]
        new_row += [1] if r > 0 else []
        rows.append(new_row)
    return rows

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    rows = generate_best(n)
    for row in rows:
        print(' '.join(map(str, row)))
